function draw({svg,width,height,progress,params,state,controls}){
 const ns='http://www.w3.org/2000/svg', mobile=width<600;
 const ink='#233942', muted='#64777b', teal='#087f83', amber='#b66a25', pale='#dce8e7';
 function el(id,tag,attrs={},value){let n=svg.querySelector('#'+id);if(!n){n=document.createElementNS(ns,tag);n.id=id;svg.appendChild(n);}for(const [k,v] of Object.entries(attrs))n.setAttribute(k,v);if(value!==undefined)n.textContent=value;return n;}
 function txt(id,x,y,s,size=14,color=ink,anchor='start'){return el(id,'text',{x,y,fill:color,'font-size':size,'font-family':'system-ui, sans-serif','text-anchor':anchor},s);}
 function line(id,x1,y1,x2,y2,color=pale,sw=1){return el(id,'line',{x1,y1,x2,y2,stroke:color,'stroke-width':sw});}
 function box(id,x,y,w,h,fill='white',stroke=pale){return el(id,'rect',{x,y,width:w,height:h,rx:5,fill,stroke});}
 svg.setAttribute('viewBox','0 0 '+width+' '+height);

 const i=Number(params.block), l=Number(params.layer), cx=mobile?104:width*.34, leaf=mobile?227:width*.64;
 txt('caption',18,25,'选一个分支，沿路径读名字',14,muted);
 txt('root',20,62,'rgnet',17); line('r0',47,69,47,98,teal,2);txt('major',20,120,'[0]',17,teal);
 for(let k=0;k<4;k++){let y=67+k*42,selected=k===i;
 line('branch'+k,50,127,cx,y+4,selected?teal:pale,selected?2:1);
 box('block'+k,cx,y-18,91,31,selected?'#edf7f6':'#f8faf9',selected?teal:pale);
 txt('btext'+k,cx+45,y+3,'block '+k,14,selected?teal:muted,'middle');}
 const y=67+i*42;line('selected',cx+91,y,leaf,y,teal,2);
 box('linear',leaf,y-18,mobile?79:132,31,'#edf7f6',teal);txt('linearlabel',leaf+(mobile?39:66),y+3,'['+l+'] Linear',mobile?12:15,teal,'middle');
 const by=mobile?263:244;
 line('separator',18,by-20,width-18,by-20);
 txt('pathhead',18,by,'索引',12,muted);txt('path',18,by+24,'rgnet[0]['+i+']['+l+'].bias',mobile?16:19);
 txt('namehead',18,by+55,'named_parameters() 的完整名称',12,muted);
 txt('name',18,by+80,'0.block '+i+'.'+l+'.bias',mobile?17:20,teal);
 txt('shape',18,by+110,'bias: ('+(l===0?'8':'4')+',)    weight: '+(l===0?'(8, 4)':'(4, 8)'),14,muted);
 return {blockIndex:i,layerIndex:l,indexPath:'rgnet[0]['+i+']['+l+'].bias',parameterName:'0.block '+i+'.'+l+'.bias',biasShape:[l===0?8:4],weightShape:l===0?[8,4]:[4,8],conditions:'原文 rgnet；ReLU 无参数；省略未选中的层与最外侧输出层。'};
}

function draw({svg,width,height,progress,params,state,controls}){
 const ns='http://www.w3.org/2000/svg', mobile=width<600;
 const ink='#233942', muted='#64777b', teal='#087f83', amber='#b66a25', pale='#dce8e7';
 function el(id,tag,attrs={},value){let n=svg.querySelector('#'+id);if(!n){n=document.createElementNS(ns,tag);n.id=id;svg.appendChild(n);}for(const [k,v] of Object.entries(attrs))n.setAttribute(k,v);if(value!==undefined)n.textContent=value;return n;}
 function txt(id,x,y,s,size=14,color=ink,anchor='start'){return el(id,'text',{x,y,fill:color,'font-size':size,'font-family':'system-ui, sans-serif','text-anchor':anchor},s);}
 function line(id,x1,y1,x2,y2,color=pale,sw=1){return el(id,'line',{x1,y1,x2,y2,stroke:color,'stroke-width':sw});}
 function box(id,x,y,w,h,fill='white',stroke=pale){return el(id,'rect',{x,y,width:w,height:h,rx:5,fill,stroke});}
 svg.setAttribute('viewBox','0 0 '+width+' '+height);

 const a=Number(params.threshold), left=34,right=width-28, span=right-left, X=v=>left+(v+10)*span/20;
 const y1=mobile?95:80,y2=mobile?208:185;
 txt('caption',18,25,'40 个等距分位点 · 非随机抽样',13,muted);
 txt('before',18,y1-26,'筛选前 z',14);txt('after',18,y2-26,'筛选后 w',14);
 line('axis1',left,y1,right,y1,muted);line('axis2',left,y2,right,y2,muted);
 for(const v of [-10,-5,0,5,10]){for(const [r,y]of [[1,y1],[2,y2]]){line('tick'+r+'x'+v,X(v),y-4,X(v),y+4,muted);txt('ticktext'+r+'x'+v,X(v),y+21,String(v),12,muted,'middle');}}
 for(let k=0;k<40;k++){const z=-10+(k+.5)*.5,w=Math.abs(z)>=a?z:0, collapsed=w===0;
 line('map'+k,X(z),y1+5,X(w),y2-6,collapsed?'#dec6ad':'#a5cccc',1);
 el('z'+k,'circle',{cx:X(z),cy:y1,r:2.6,fill:collapsed?amber:teal});
 el('w'+k,'circle',{cx:X(w),cy:y2,r:collapsed?3:2.6,fill:collapsed?amber:teal});}
 for(const v of [-a,a]){const key=v<=0?'minus':'plus';line('cut'+key,X(v),y1-14,X(v),y1+9,amber,2);}
 const by=mobile?292:269, zero=a/10, tail=(10-a)/20;
 txt('probtitle',18,by-20,'概率质量（不是密度）',13,muted);
 const bw=width-36, t=bw*tail,c=bw*zero;
 box('negative',18,by,t,16,teal,teal);box('zero',18+t,by,c,16,amber,amber);box('positive',18+t+c,by,t,16,teal,teal);
 txt('negprob',18,by+41,'负值 '+(tail*100).toFixed(0)+'%',13,teal);
 txt('zeroprob',width/2,by+41,'零 '+(zero*100).toFixed(0)+'%',14,amber,'middle');txt('posprob',width-18,by+41,'正值 '+(tail*100).toFixed(0)+'%',13,teal,'end');
 txt('rule',18,by+73,'|z| < a → 0；其余保持原值',14);
 txt('support',18,by+97,'z ∼ U(−10, 10)；a = '+a.toFixed(1),13,muted);
 return {threshold:a,zeroProbability:zero,negativeProbability:tail,positiveProbability:tail,quantilePoints:Array.from({length:40},(_,k)=>{const z=-10+(k+.5)*.5;return {z,w:Math.abs(z)>=a?z:0};}),conditions:'连续均匀分布，阈值 a∈[0,10]；a=5 对应原文。40 个点是确定性示意，概率由区间长度解析计算，阈值端点的单点概率为零。'};
}

function draw({svg,width,height,progress,params,state,controls}){
 const ns='http://www.w3.org/2000/svg', mobile=width<600;
 const ink='#233942', muted='#64777b', teal='#087f83', amber='#b66a25', pale='#dce8e7';
 function el(id,tag,attrs={},value){let n=svg.querySelector('#'+id);if(!n){n=document.createElementNS(ns,tag);n.id=id;svg.appendChild(n);}for(const [k,v] of Object.entries(attrs))n.setAttribute(k,v);if(value!==undefined)n.textContent=value;return n;}
 function txt(id,x,y,s,size=14,color=ink,anchor='start'){return el(id,'text',{x,y,fill:color,'font-size':size,'font-family':'system-ui, sans-serif','text-anchor':anchor},s);}
