 txt('x',start,yy+24,'x = 1',14);
 const u1=start+(mobile?58:95),u2=u1+bw+gap;
 line('xin',start+40,yy+19,u1,yy+19,teal,2);
 box('u1',u1,yy,bw,39,'#edf7f6',teal);box('u2',u2,yy,bw,39,'#edf7f6',teal);
 txt('use1',u1+bw/2,yy+24,'× w + 1',14,teal,'middle');txt('use2',u2+bw/2,yy+24,'× w + 1',14,teal,'middle');line('forward',u1+bw,yy+19,u2,yy+19,teal,2);
 txt('h',u1+bw/2,yy+64,'h = '+fmt(h),13,muted,'middle');txt('y',u2+bw/2,yy+64,'y = '+fmt(y),13,muted,'middle');
 const sx=(u1+u2+bw)/2,sy=mobile?170:164;
 line('tie1',u1+bw/2,yy+40,sx,sy-19,teal);line('tie2',u2+bw/2,yy+40,sx,sy-19,teal);
 box('shared',sx-68,sy-19,136,32,'white',teal);txt('sharedtxt',sx,sy+2,'同一 w = '+w.toFixed(2),14,teal,'middle');
 const by=mobile?224:213;txt('loss',18,by,'L = ½(y − 2)² = '+fmt(.5*e*e),14);
 txt('formula',18,by+26,'g₁ = (y − 2)w     g₂ = (y − 2)h',mobile?13:15,muted);
 const left=mobile?77:170,right=width-(mobile?69:105), zero=(left+right)/2,S=(right-left)/24;
 const top=by+52,dy=34;
 for(let j=0;j<3;j++){const val=[g1,g2,g][j],yy2=top+j*dy;
 txt('glab'+j,18,yy2+5,['第1次','第2次','相加'][j],13,j===2?ink:muted);
 line('base'+j,left,yy2,right,yy2,pale,1);
 const end=zero+val*S;el('bar'+j,'rect',{x:Math.min(zero,end),y:yy2-7,width:Math.max(.8,Math.abs(end-zero)),height:14,fill:j===2?teal:amber,rx:2});
 txt('gval'+j,width-18,yy2+5,fmt(val),13,j===2?teal:amber,'end');}
 line('gzero',zero,top-14,zero,top+dy*2+12,muted,1);
 for(const v of [-12,0,12])txt('gtick'+v,zero+v*S,top+dy*2+30,String(v),12,muted,'middle');
 txt('gaxis',18,top+dy*2+54,'权重梯度 ∂L/∂w = g₁ + g₂',14,teal);
 return {x,bias:b,target,w,h,y,loss:.5*e*e,firstUseGradient:g1,secondUseGradient:g2,totalWeightGradient:g,conditions:'共享标量线性层连续使用两次；x=1，两个固定偏置都为1，目标2；省略 ReLU，固定偏置，仅考察权重的偏导。手选参数，无训练。梯度轴固定 [-12,12]。'};
